const BASE_LINKS = [
  { label: 'Dashboard', path: '/restaurante', icon: 'LayoutDashboard' },
  { label: 'Conferências', path: '/restaurante/relatorios', icon: 'BarChart3' },
  { label: 'Produtos', path: '/restaurante/produtos', icon: 'Package' },
  { label: 'Clientes', path: '/restaurante/clientes', icon: 'UserRound' },
  { label: 'Financeiro', path: '/restaurante/financeiro', icon: 'Wallet' },
  { label: 'Caixa', path: '/restaurante/caixa', icon: 'PiggyBank' },
  { label: 'Designer', path: '/restaurante/aparencia', icon: 'Paintbrush' },
  { label: 'Cardápio Digital', path: '/restaurante/cardapio-digital', icon: 'BookOpen' },
  { label: 'Plano', path: '/restaurante/plano', icon: 'CreditCard' },
  { label: 'Sessão', path: '/restaurante/sessao', icon: 'Clock' },
];

// Servem tanto Delivery quanto Salão — só somem se a empresa não tem NENHUM módulo ativo.
const COMPARTILHADO_LINKS = [
  { label: 'Cozinha', path: '/restaurante/cozinha', icon: 'ChefHat' },
  { label: 'Combos', path: '/restaurante/combos', icon: 'Boxes' },
  { label: 'Pedidos', path: '/restaurante/pedidos', icon: 'ClipboardList' },
];

const DELIVERY_LINKS = [
  { label: 'Delivery', path: '/restaurante/delivery', icon: 'Truck' },
  { label: 'Entregas', path: '/restaurante/entregas', icon: 'Bike' },
  { label: 'Motoboys', path: '/restaurante/motoboys', icon: 'Users' },
  { label: 'Impulsionar', path: '/restaurante/impulsionar', icon: 'Rocket' },
];

const COPA_LINKS = [
  { label: 'Produção', path: '/restaurante/producao', icon: 'CookingPot' },
  { label: 'Bar', path: '/restaurante/bar', icon: 'Beer' },
];

const SALAO_LINKS = [
  { label: 'Salão', path: '/restaurante/salao', icon: 'UtensilsCrossed' },
  { label: 'Venda Balcão', path: '/restaurante/venda-balcao', icon: 'ShoppingCart' },
  { label: 'Chamada', path: '/restaurante/chamada', icon: 'Volume2' },
  { label: 'Garçons', path: '/restaurante/garcons', icon: 'Contact' },
  { label: 'Mesas', path: '/restaurante/mesas', icon: 'Table2' },
  { label: 'Impressoras', path: '/restaurante/impressoras', icon: 'Printer' },
];

// Pontos de preparo customizados (Churrasqueira, Drinks...) usam o mesmo requisito de
// visibilidade da Cozinha — precisam de algum módulo ativo pra fazer sentido no menu.
const PONTOS_PREPARO_CADASTRO = { label: 'Pontos de Preparo', path: '/restaurante/pontos-preparo', icon: 'LayoutGrid' };

// Estabelecimento tipo ≠ Restaurante (farmácia, material de construção...) chama
// o entregador de "Entregadores" no menu, em vez de "Motoboys" (termo mais
// específico de delivery de comida).
export const getRestauranteNavLinks = (moduloDelivery, moduloSalao, pontosPreparo = [], tipoRestaurante = true) => {
  const temAlgumModulo = moduloDelivery || moduloSalao;
  const deliveryLinks = tipoRestaurante
    ? DELIVERY_LINKS
    : DELIVERY_LINKS.map((l) => (l.path === '/restaurante/motoboys' ? { ...l, label: 'Entregadores' } : l));
  const links = [
    ...BASE_LINKS.slice(0, 2), // Dashboard, Relatórios
    ...(moduloDelivery ? deliveryLinks.slice(0, 1) : []), // Delivery
    ...(temAlgumModulo ? COMPARTILHADO_LINKS.slice(0, 1) : []), // Cozinha
    ...(temAlgumModulo ? [PONTOS_PREPARO_CADASTRO, ...pontosPreparo] : []), // Cadastro + pontos criados
    ...(moduloSalao ? COPA_LINKS : []), // Produção, Bar
    ...BASE_LINKS.slice(2, 3), // Produtos
    ...(temAlgumModulo ? COMPARTILHADO_LINKS.slice(1) : []), // Combos, Pedidos
    ...(moduloDelivery ? deliveryLinks.slice(1) : []), // Entregas, Motoboys/Entregadores
    ...BASE_LINKS.slice(3), // Clientes...Sessão
    ...(moduloSalao ? SALAO_LINKS : []), // Salão, Garçons, Impressoras
  ];
  // Menu lateral em ordem alfabética (pedido do usuário) — a ordem acima só
  // controla quais links entram conforme os módulos ativos. Dashboard fica
  // fixo no topo, fora da ordenação.
  const [dashboard, resto] = [links.find((l) => l.path === '/restaurante'), links.filter((l) => l.path !== '/restaurante')];
  resto.sort((a, b) => a.label.localeCompare(b.label, 'pt-BR'));
  return dashboard ? [dashboard, ...resto] : resto;
};

const totalSalao = filaAguardando.filter((e) => e.tipo === 'salao').length + filaEmPreparo.filter((e) => e.tipo === 'salao').length;

// Modo token: mostrar login se não autenticado
if (modoToken && !authed) {
  return <CozinhaLogin onLogin={() => setAuthed(true)} />;
}

if (loading) return (
  <div className="min-h-screen bg-[#1A1A1A] flex items-center justify-center">
    <div className="w-10 h-10 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
  </div>
);

return (
  <div className="min-h-screen bg-[#111111]">
    <header className="bg-[#1A1A1A] border-b border-[#2A2A2A] px-5 py-3">
      <div className="flex items-center gap-4 mb-3">
        {modoToken ? (
          <button onClick={() => { clearCozinhaToken(); window.location.reload(); }}
            className="p-2 text-[#71717A] hover:text-red-400 rounded-lg hover:bg-[#2A2A2A]" title="Sair">
            <Icon name="LogOut" size={18} />
          </button>
        ) : (
          <button onClick={() => navigate('/restaurante')} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
            <Icon name="ArrowLeft" size={18} />
          </button>
        )}
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-[#FF441F] rounded-lg flex items-center justify-center flex-shrink-0">
            <Icon name="ChefHat" size={16} className="text-white" />
          </div>
          <div>
            <p className="text-white font-black text-base leading-none">Painel da Cozinha</p>
            <p className="text-[#71717A] text-xs">{restauranteNome}</p>
          </div>
        </div>
        <div className="ml-auto flex items-center gap-2">
          <div className="flex items-center gap-2 text-xs text-[#71717A]">
            <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
            {lastUpdate?.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) ?? '—'}
          </div>
          {/* Botão copiar link — só para o dono, não no modo token */}
          {!modoToken && (
            <button
              onClick={copiarLinkCozinha}
              disabled={gerandoLink}
              title="Copiar link de acesso para a cozinha"
              className={`p-2 rounded-lg transition-colors disabled:opacity-50 ${copiadoLink ? 'text-green-400 bg-green-400/10' : 'text-[#71717A] hover:text-white hover:bg-[#2A2A2A]'}`}
            >
              <Icon name={gerandoLink ? 'Loader2' : copiadoLink ? 'Check' : 'Link'} size={16}

import React from 'react';
import Icon from '../AppIcon';
import { formatDuracao } from '../../utils/formatDuracao';

const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
const PAYMENT_LABELS = { pix: 'PIX', credit_card: 'Cartão', debit_card: 'Débito', cash: 'Dinheiro' };

const BUCKET_INFO = {
  aguardando: { label: 'Aguardando Preparo', border: 'border-blue-300 bg-blue-50', badge: 'bg-blue-100 text-blue-800' },
  preparando: { label: 'Em Preparo', border: 'border-orange-300 bg-orange-50', badge: 'bg-orange-100 text-orange-800' },
  pronto: { label: 'Pronto', border: 'border-emerald-300 bg-emerald-50', badge: 'bg-emerald-100 text-emerald-800' },
};

// Pedido de delivery agrupado (mesmo visual do OrderCard da tela Cozinha) — usado em
// Produção/Bar pra manter o mesmo padrão de card em todas as praças. Diferença chave:
// aqui a ação avança/volta só os ITENS deste setor específico (não o status do pedido
// inteiro), porque um pedido pode ter itens espalhados por mais de uma praça — só o
// backend (marcarItemPronto) decide quando TODAS já terminaram pra liberar pro motoboy.
const PedidoDeliveryCard = ({ pedido, itens, posicao, now, bucket, onIniciarPreparo, onMarcarPronto, onVoltar, atualizando, highlighted = false, codigoBarras = null, cardId = null }) => {
  const isAtualizando = atualizando === pedido.id;
  const tempoDecorrido = now - new Date(pedido.created_at).getTime();
  const c = BUCKET_INFO[bucket];
  const ehPrioridade = posicao === 1 && bucket !== 'pronto';

  return (
    <div
      id={cardId ?? `pedido-delivery-${pedido.id}`}
      className={`rounded-2xl border-2 overflow-hidden flex flex-col transition-all duration-300 ${
        highlighted
          ? 'border-yellow-400 bg-yellow-50 shadow-xl shadow-yellow-300/40 scale-[1.02]'
          : ehPrioridade
          ? 'border-yellow-400 bg-white'
          : c.border
      }`}
    >
      {ehPrioridade && !highlighted && (
        <div className="bg-yellow-400 px-4 py-1 flex items-center gap-1.5">
          <p className="text-[10px] font-black text-yellow-900 uppercase tracking-wide">Próximo da fila</p>
        </div>
      )}

      <div className="px-4 pt-3 pb-2 flex items-start justify-between gap-2">
        <div>
          <div className="flex items-center gap-2 mb-0.5">
            <span className={`w-6 h-6 flex-shrink-0 rounded-lg flex items-center justify-center text-xs font-black ${ehPrioridade ? 'bg-yellow-400 text-black' : 'bg-[#E4E4E7] text-[#27272A]'}`}>
              {posicao}
            </span>
            <p className="text-2xl font-black text-[#18181B]">#{pedido.id}</p>
            <span className={`text-xs px-2 py-0.5 rounded-full font-bold ${c.badge}`}>{c.label}</span>
          </div>
          {pedido.customers?.name && (
            <p className="text-sm font-semibold text-[#27272A]">{pedido.customers.name}</p>
          )}
          <p className="text-xs text-[#71717A] mt-0.5 flex items-center gap-1">
            <Icon name="Clock" size={11} />
            {new Date(pedido.created_at).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
            <span className="ml-1 font-semibold font-mono text-green-600">· {formatDuracao(tempoDecorrido)}</span>
          </p>
        </div>
        <div className="flex flex-col items-end gap-1.5 flex-shrink-0">
          <span className="text-[10px] px-2 py-0.5 rounded-full font-bold bg-sky-100 text-sky-700">Delivery</span>
          {codigoBarras && (
            <div className="flex items-center justify-center gap-1 px-2 py-1 bg-[#F4F4F5] rounded-lg">
              <Icon name="Barcode" size={11} className="text-[#71717A]" />
              <span className="text-[10px] font-mono text-[#71717A]">{codigoBarras}</span>
            </div>
          )}
        </div>
      </div>

      <div className="px-4 py-3 bg-white mx-3 rounded-xl mb-3 border border-[#E4E4E7] flex-1">
        <div className="space-y-2">
          {itens.map((item) => (
            <div key={item.id} className="flex items-start gap-2">
              <span className="w-7 h-7 bg-[#FF441F] text-white font-black text-sm rounded-lg flex items-center justify-center flex-shrink-0 mt-0.5">
                {item.quantity}
              </span>
              <p className="text-sm font-semibold text-[#18181B] leading-tight">{item.product_name}</p>
            </div>
          ))}
        </div>
        {(pedido.total != null || pedido.payment_method) && (
          <div className="flex items-center justify-between mt-3 pt-2 border-t border-[#F4F4F5]">
            <span className="text-xs text-[#71717A]">{PAYMENT_LABELS[pedido.payment_method] ?? pedido.payment_method}</span>
            {pedido.total != null && <span className="text-sm font-black text-[#FF441F]">{fmt(pedido.total)}</span>}
          </div>
        )}
      </div>

      {pedido.outras_pracas?.length > 0 && (
        <div className="mx-3 mb-3 -mt-1 bg-amber-50 border border-amber-200 rounded-xl px-3 py-2">
          <p className="text-xs font-bold text-amber-800 mb-1 flex items-center gap-1.5">
            <Icon name="Info" size={13} className="text-amber-600 flex-shrink-0" />
            Pedido também tem:
          </p>
          <div className="space-y-0.5">
            {pedido.outras_pracas.map((g) => (
              <p key={g.setor} className="text-xs text-amber-800 leading-snug flex items-center gap-1.5">
                <Icon name={g.pronto ? 'CheckCircle2' : 'Clock'} size={12} className={g.pronto ? 'text-emerald-600' : 'text-amber-600'} />
                {g.itens.join(', ')} <span className="font-semibold">({g.setor}{g.pronto ? ' — pronto' : ' — aguardando'})</span>
              </p>
            ))}
          </div>
        </div>
      )}

      {bucket === 'pronto' ? (
        <div className="px-3 pb-3">
          <button
            disabled={isAtualizando}
            onClick={onVoltar}
            className="w-full flex items-center justify-center gap-1.5 py-2 bg-white border border-[#E4E4E7] rounded-xl text-xs font-bold text-[#71717A] hover:bg-[#F4F4F5] disabled:opacity-40 transition-colors"
          >
            <Icon name="Undo2" size={13} /> Desfazer — clicou errado
          </button>
        </div>
      ) : (
        <div className="px-3 pb-3 flex gap-2">
          {bucket === 'preparando' && (
            <button
              disabled={isAtualizando}
              onClick={onVoltar}
              className="flex items-center justify-center gap-1.5 px-3 py-2.5 bg-white border border-[#E4E4E7] rounded-xl text-xs font-bold text-[#71717A] hover:bg-[#F4F4F5] disabled:opacity-40 transition-colors"
            >
              <Icon name="ArrowLeft" size={13} /> Ag. Preparo
            </button>
          )}
          <button
            disabled={isAtualizando}
            onClick={bucket === 'aguardando' ? onIniciarPreparo : onMarcarPronto}
            className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-white text-sm font-black rounded-xl disabled:opacity-50 transition-colors shadow-md ${
              bucket === 'aguardando' ? 'bg-orange-500 hover:bg-orange-600' : 'bg-purple-600 hover:bg-purple-700'
            }`}
          >
            {isAtualizando ? (
              <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
            ) : (
              <>
                <Icon name={bucket === 'aguardando' ? 'ChefHat' : 'Package'} size={15} />
                {bucket === 'aguardando' ? 'Iniciar Preparo' : 'Marcar Pronto'}
              </>
            )}
          </button>
        </div>
      )}
    </div>
  );
};

export default PedidoDeliveryCard;

